/* global silenceConsoleErrors */
/**
 * STARFORGED COMPANION
 * tests/unit/portraitLateFirstGeneration.test.js
 *
 * Known-issues PORTRAIT-LATE-FIRST-GENERATION (found while confirming
 * GENERATE-PORTRAIT-AFTER-REGEN): an entity is given one first portrait,
 * however many generations of it are asked for while its image is out.
 *
 * generatePortrait checked its caller's copy of the record before the image
 * call and linked its image, unchecked, once it came back. A new NPC card's
 * portrait is generated by its seed, fire-and-forget, and the Entities panel
 * offers Generate until a portrait is linked: the GM's press while the seed's
 * image was out bought a second image, and the later link won. Pressed, and
 * then Regenerate, before the seed's image came back, the late seed portrait
 * replaced the locked regenerated one with a fresh unlocked one — three images
 * billed, and Regenerate offered again. Now one image is made at a time for
 * an entity on a client (a second generation waits for the first and gets its
 * portrait), and a portrait that comes back after another was linked meanwhile
 * — another GM's, say — leaves the linked one standing and is not stored.
 *
 * Driven on a booted table of two GMs: the real generator, the Art Cache
 * storage and the record writes, with the image call stubbed.
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach, afterEach, vi } from 'vitest';

// Each image call takes the next step: { hold: Promise } waits for it.
const art = vi.hoisted(() => ({ calls: 0, next: [] }));
vi.mock('../../src/art/openRouterImage.js', () => ({
  generateOpenRouterImage: vi.fn(async () => {
    art.calls += 1;
    const step = art.next.shift();
    if (step?.hold) await step.hold;
    return 'A'.repeat(400);
  }),
}));

import { simulateTable, USERS, MODULE_ID } from '../helpers/multiClient.js';
import { deferred } from '../helpers/faults.js';
import { CampaignStateSchema } from '../../src/schemas.js';

let nextId = 0;

/** A JournalEntry that keeps its pages (the tests/setup.js stub keeps none) — the Art Cache's entries. */
function makeJournal(data) {
  const id = `jrnl${String(++nextId).padStart(12, '0')}`;
  const journal = {
    id, name: data.name, folder: data.folder ?? null,
    flags: JSON.parse(JSON.stringify(data.flags ?? {})),
    pages: { contents: [] },
    async createEmbeddedDocuments(_type, list) {
      return list.map((d) => {
        const page = {
          id: `page${String(++nextId).padStart(12, '0')}`,
          name: d.name, type: d.type ?? 'text', text: d.text ?? {},
          flags: JSON.parse(JSON.stringify(d.flags ?? {})),
          getFlag(scope, key) { return this.flags?.[scope]?.[key]; },
          async setFlag(scope, key, value) { (this.flags[scope] ??= {})[key] = JSON.parse(JSON.stringify(value)); return this; },
          async update() { return this; },
        };
        journal.pages.contents.push(page);
        return page;
      });
    },
    getFlag(scope, key) { return this.flags?.[scope]?.[key]; },
    async setFlag(scope, key, value) { (this.flags[scope] ??= {})[key] = value; return this; },
    async update(changes) { Object.assign(this, changes); return this; },
  };
  return journal;
}

let table;
let savedJournalEntry;
let vance;
const record = () => vance.flags[MODULE_ID].connection;
// The portraits the Art Cache holds for Vance.
const vancePortraits = () => table.journal.contents
  .map(e => e.pages?.contents?.[0]?.flags?.[MODULE_ID]?.artAsset)
  .filter(a => a?.entityId === 'rec-vance');

beforeAll(async () => { table = await simulateTable({ users: [USERS.GM, USERS.GM2] }); }, 30_000);
afterAll(() => table?.teardown());

beforeEach(async () => {
  art.calls = 0;
  art.next = [];
  await table.reset({ world: { settings: {
    chronicleAutoEntry: false, autoSeedConnection: false,
    campaignState: { ...CampaignStateSchema, connectionIds: ['npc-vance'] },
  } } });
  for (const id of ['gm-1', 'gm-2']) await table.client(id).setSetting('openRouterApiKey', 'sk-or-test');
  savedJournalEntry = globalThis.JournalEntry;
  globalThis.JournalEntry = {
    async create(data) {
      const j = makeJournal(data);
      globalThis.game.journal._set(j.id, j);
      return j;
    },
  };
  vance = table.addActor({
    id: 'npc-vance', name: 'Vance', type: 'character',
    flags: { [MODULE_ID]: { entityType: 'connection', connection: {
      _id: 'rec-vance', name: 'Vance', role: 'Pilot', rank: 'dangerous', active: true, history: [],
      portraitSourceDescription: 'A weathered pilot in a patched flight suit',
    } } },
  });
  await table.settle();
  silenceConsoleErrors();
});
afterEach(() => { globalThis.JournalEntry = savedJournalEntry; });

/** Start fn(generator, campaignState) on a GM's client; its promise. */
async function startOn(id, fn) {
  const gm = table.client(id);
  const generator = await gm.import('../../src/art/generator.js');
  return gm.run(() => fn(generator, game.settings.get(MODULE_ID, 'campaignState')));
}
const generate   = (id) => startOn(id, (g, cs) => g.generatePortrait('npc-vance', 'connection', record(), cs));
const regenerate = (id) => startOn(id, (g, cs) => g.regeneratePortrait('npc-vance', 'connection', record(), cs));

/** The seed's portrait (seedConnectionActor's fire-and-forget call), its image held until `image.resolve()`. */
async function seedPortraitHeld(id = 'gm-1') {
  const image = deferred();
  art.next = [{ hold: image.promise }];
  const seed = generate(id);
  await vi.waitFor(() => expect(art.calls).toBe(1));   // the seed's image is out
  return { seed, image };
}

describe('an entity is given one first portrait (PORTRAIT-LATE-FIRST-GENERATION)', () => {
  it('the GM\'s Generate pressed while the seed\'s portrait is being made waits for it: one image, one portrait', async () => {
    const { seed, image } = await seedPortraitHeld();

    const pressed = generate('gm-1');
    await new Promise(r => setTimeout(r, 20));   // the press runs as far as it can while the seed's image is out
    image.resolve();
    const [seeded, generated] = await Promise.all([seed, pressed]);
    await table.settle();

    // It bought a second image, and the later link won.
    expect(art.calls).toBe(1);
    expect(generated?._id).toBe(seeded?._id);
    expect(record().portraitId).toBe(seeded._id);
    expect(vancePortraits()).toHaveLength(1);
  }, 30_000);

  it('a first portrait that comes back after another GM generated and regenerated one leaves the locked portrait standing', async () => {
    const { seed, image } = await seedPortraitHeld('gm-1');

    await generate('gm-2');
    await table.settle();
    const regenerated = await regenerate('gm-2');
    await table.settle();
    expect(regenerated, 'the other GM\'s regeneration landed (setup)').toMatchObject({ regenerationUsed: true, locked: true });

    image.resolve();
    await seed;
    await table.settle();

    // The late seed portrait replaced it, unlocked — Regenerate offered again.
    expect(record().portraitId).toBe(regenerated._id);
    expect(vancePortraits(), 'the late image is not stored: the first and the regenerated portrait').toHaveLength(2);
  }, 30_000);

  it('control: one Generate makes one portrait and links it', async () => {
    const asset = await generate('gm-1');
    await table.settle();

    expect(art.calls).toBe(1);
    expect(record().portraitId).toBe(asset._id);
  }, 30_000);

  it('control: once the first generation is done, a portrait whose link names nothing stored is made again', async () => {
    await vance.setFlag(MODULE_ID, 'connection', { ...record(), portraitId: 'art-deleted' });   // its Art Cache entry deleted

    const asset = await generate('gm-1');
    await table.settle();

    expect(art.calls).toBe(1);
    expect(record().portraitId).toBe(asset._id);
  }, 30_000);
});
